require_once __DIR__ . '/../_admin.php'; $input=adminMethod(['GET','POST']);$pdo=Database::getInstance();[$session,$role]=requireAdmin($pdo,$input);
if($_SERVER['REQUEST_METHOD']==='GET'){ requireAdminRole($role,['finance','super_admin'],'view wallets');$stmt=$pdo->query("SELECT w.uuid,w.user_id,w.currency_code,w.available_balance,w.pending_balance,w.status,w.updated_at,u.full_name,u.email FROM wallets w JOIN users u ON u.id=w.user_id ORDER BY w.updated_at DESC LIMIT 200");jsonResponse(['success'=>true,'wallets'=>$stmt->fetchAll()]); }
if(!in_array($role,['finance','super_admin'],true))jsonResponse(['success'=>false,'error'=>'Your role cannot change wallets.'],403);$uuid=trim((string)($input['wallet_uuid']??''));$status=(string)($input['status']??'');if($uuid===''||!in_array($status,['active','frozen','closed'],true))jsonResponse(['success'=>false,'error'=>'Invalid wallet update.'],422);$stmt=$pdo->prepare('UPDATE wallets SET status=? WHERE uuid=?');$stmt->execute([$status,$uuid]);if(!$stmt->rowCount())jsonResponse(['success'=>false,'error'=>'Wallet not found.'],404);adminAudit($pdo,(int)$session['admin']['id'],'wallet.status_changed','wallet',$uuid,['status'=>$status]);jsonResponse(['success'=>true]);
